            if ($functionText -notmatch '\[MaesterTest\(') {
                $functionText = $functionText -replace "(?s)^(function [^\{]+\{)", "`$1`n    $($attribute.Replace("`n", "`n    "))`n    [CmdletBinding()]"
            }
            $content = (@($functionText) + @($helpers)) -join "`n`n"
            $target = Join-Path $OutputPath "Test.$id.ps1"
            $targetMd = Join-Path $OutputPath "Test.$id.md"
            if ((Test-Path -LiteralPath $target) -and -not $Force) {
                [pscustomobject]@{ Id = $id; Source = "$($file.FullName):$($it.Extent.StartLineNumber)"; Output = $target; Status = 'Skipped'; Notes = 'The native test already exists; use -Force to overwrite it.' }
                continue
            }
            if ($PSCmdlet.ShouldProcess($target, "Write native test $id")) {
                $null = New-Item -ItemType Directory -Path $OutputPath -Force
                Set-Content -LiteralPath $target -Value $content -Encoding utf8
                Set-Content -LiteralPath $targetMd -Value $markdown -Encoding utf8
                $check = Read-MtNativeTest -Path $target
                if ($check.Errors.Count -gt 0) { $status = 'NeedsReview'; $notes.Add("Validation: $(($check.Errors | ForEach-Object { $_.Message }) -join ' ')") }
            }
            [pscustomobject]@{ Id = $id; Source = "$($file.FullName):$($it.Extent.StartLineNumber)"; Output = $target; Status = $status; Notes = ($notes -join ' ') }
----
    # (?m)$ matches only before LF, so allow a CR in between for CRLF templates (Windows checkouts).
    return $content -replace '(?m)[ \t]+(?=\r?$)', ''
}

function CreateFile($folderPath, $fileName, $content) {
    $filePath = Join-Path $folderPath $fileName
    if ($content -match "`r`n") {
        $newLine = "`r`n"
    } else {
        $newLine = "`n"
    }
    $content = RemoveTrailingWhitespace $content
    $content = $content -replace '(\r?\n)+$', ''
    [System.IO.File]::WriteAllText($filePath, "$content$newLine", [System.Text.UTF8Encoding]::new($false))
}

----
$orcaInternal = Join-Path $repo 'powershell/internal/generated/orca'
if (-not $OutputPath) { $OutputPath = Join-Path $repo 'tests/orca' }
$null = New-Item -Path $OutputPath -ItemType Directory -Force

function Write-OrcaGeneratedContent {
    param (
        [Parameter(Mandatory)]
        [string] $Path,

        [Parameter(Mandatory)]
        [string] $Value
    )

    if ($Value -match "`r`n") {
        $newLine = "`r`n"
    } else {
        $newLine = "`n"
    }
    $cleanValue = $Value -replace '(?m)[ \t]+(?=\r?$)', ''
    $cleanValue = $cleanValue -replace '(\r?\n)+$', ''
    # A CRLF checkout gives the templates CRLF while the generated lines are joined with LF: write one kind.
    if ($newLine -eq "`r`n") { $cleanValue = $cleanValue -replace '(?<!\r)\n', "`r`n" }
    [System.IO.File]::WriteAllText($Path, "$cleanValue$newLine", [System.Text.UTF8Encoding]::new($false))
}

----
$config.ConfigVersion = $ConfigVersion
$updatedContent = $config | ConvertTo-Json -Depth 10 -WarningAction Stop

try { $null = $updatedContent | ConvertFrom-Json } catch { throw "Output is not valid JSON after stamping: $_" }

$utf8NoBom = [System.Text.UTF8Encoding]::new($false)
$resolvedOutputPath = (Resolve-Path -LiteralPath $ConfigPath).ProviderPath
[System.IO.File]::WriteAllText($resolvedOutputPath, $updatedContent, $utf8NoBom)

Write-Host "Stamped ${ConfigPath}: ModuleVersion=$ModuleVersion, ConfigVersion=$ConfigVersion"
---
[CmdletBinding()]
param()

$repoRoot = (Resolve-Path "$PSScriptRoot/../..").Path
$manifest = Join-Path $repoRoot 'powershell/Maester.psd1'
$names = @(Get-ChildItem -Path (Join-Path $repoRoot 'powershell/public') -Recurse -File -Filter '*.ps1' | ForEach-Object { $_.BaseName } | Sort-Object -Unique)
$text = [System.IO.File]::ReadAllText($manifest)
$list = ($names | ForEach-Object { "        '$_'" }) -join ",`n"
$updated = [regex]::Replace($text, '(?s)    FunctionsToExport    = @\(.*?\n    \)', "    FunctionsToExport    = @(`n$list`n    )")
[System.IO.File]::WriteAllText($manifest, $updated, [System.Text.UTF8Encoding]::new($false))
Write-Information "FunctionsToExport: $($names.Count) functions." -InformationAction Continue
---
}

function Read-TextFile {
    param([string] $File)
    $bytes = [System.IO.File]::ReadAllBytes($File)
    $hasBom = $bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF
    $skip = if ($hasBom) { 3 } else { 0 }
    [pscustomobject]@{ Text = [System.Text.UTF8Encoding]::new($false).GetString($bytes, $skip, $bytes.Length - $skip); HasBom = $hasBom }
}

function Write-JsonFile {
    # The JSON files this script touches are all in ConvertTo-Json's own layout, LF, no byte order mark.
    param([string] $File, [object] $Value)
    $json = ((ConvertTo-Json -InputObject $Value -Depth 10) -replace "`r`n", "`n").TrimEnd("`n") + "`n"
    [System.IO.File]::WriteAllText($File, $json, [System.Text.UTF8Encoding]::new($false))
}

